# Setup response routing must never silently fork into another active ephemeral
# panel. Log every transition, directly target the clicked message on recovery,
# and if in-place recovery fails show an error only, not a second setup view.
replace(
    "stoney_verify/commands_ext/public_setup_solid.py",
    '''async def _safe_defer_update(interaction: discord.Interaction) -> None:\n    try:\n        if not interaction.response.is_done():\n            await interaction.response.defer(thinking=False)\n    except Exception:\n        pass\n\n\nasync def _edit_or_followup(\n    interaction: discord.Interaction,\n    *,\n    embed: discord.Embed,\n    view: Optional[discord.ui.View] = None,\n) -> None:\n    try:\n        if interaction.response.is_done():\n            await interaction.edit_original_response(embed=embed, view=view)\n        else:\n            await interaction.response.edit_message(embed=embed, view=view)\n        return\n    except Exception:\n        pass\n\n    try:\n        await interaction.followup.send(\n            embed=embed,\n            view=view,\n            ephemeral=True,\n            allowed_mentions=discord.AllowedMentions.none(),\n        )\n    except Exception:\n        pass\n\n\nasync def _send_ephemeral(\n    interaction: discord.Interaction,\n    *,\n    embed: discord.Embed,\n    view: Optional[discord.ui.View] = None,\n) -> None:\n    try:\n        if interaction.response.is_done():\n            await interaction.followup.send(\n                embed=embed,\n                view=view,\n                ephemeral=True,\n                allowed_mentions=discord.AllowedMentions.none(),\n            )\n        else:\n            await interaction.response.send_message(\n                embed=embed,\n                view=view,\n                ephemeral=True,\n                allowed_mentions=discord.AllowedMentions.none(),\n            )\n    except Exception:\n        pass\n''',
    '''def _setup_interaction_log(stage: str, interaction: discord.Interaction, **details: Any) -> None:\n    try:\n        data = interaction.data if isinstance(interaction.data, dict) else {}\n        fields = {\n            "stage": stage,\n            "interaction": int(getattr(interaction, "id", 0) or 0),\n            "guild": int(getattr(getattr(interaction, "guild", None), "id", 0) or 0),\n            "user": int(getattr(getattr(interaction, "user", None), "id", 0) or 0),\n            "message": int(getattr(getattr(interaction, "message", None), "id", 0) or 0),\n            "custom_id": str(data.get("custom_id") or ""),\n            "response_done": bool(interaction.response.is_done()),\n        }\n        fields.update(details)\n        print("🔎 setup_runtime " + " ".join(f"{key}={value}" for key, value in fields.items()))\n    except Exception:\n        pass\n\n\nasync def _safe_defer_update(interaction: discord.Interaction) -> None:\n    if interaction.response.is_done():\n        return\n    try:\n        await interaction.response.defer(thinking=False)\n        _setup_interaction_log("acknowledged", interaction)\n    except Exception as exc:\n        _setup_interaction_log(\n            "ack_failed",\n            interaction,\n            error=f"{type(exc).__name__}:{str(exc)[:180]}",\n        )\n        raise\n\n\nasync def _edit_or_followup(\n    interaction: discord.Interaction,\n    *,\n    embed: discord.Embed,\n    view: Optional[discord.ui.View] = None,\n) -> None:\n    primary_error: Optional[Exception] = None\n    try:\n        if interaction.response.is_done():\n            await interaction.edit_original_response(embed=embed, view=view)\n            route = "edit_original_response"\n        else:\n            await interaction.response.edit_message(embed=embed, view=view)\n            route = "response.edit_message"\n        _setup_interaction_log("edit_ok", interaction, route=route)\n        return\n    except Exception as exc:\n        primary_error = exc\n        _setup_interaction_log(\n            "edit_failed",\n            interaction,\n            error=f"{type(exc).__name__}:{str(exc)[:180]}",\n        )\n\n    # For component interactions, recover against the exact clicked message.\n    # Never silently create a second active setup panel, which lets old/new\n    # views race and makes state appear to change on the wrong screen.\n    message = getattr(interaction, "message", None)\n    edit_message = getattr(message, "edit", None)\n    if message is not None and callable(edit_message):\n        try:\n            await edit_message(embed=embed, view=view)\n            _setup_interaction_log("direct_message_recovery_ok", interaction)\n            return\n        except Exception as exc:\n            _setup_interaction_log(\n                "direct_message_recovery_failed",\n                interaction,\n                error=f"{type(exc).__name__}:{str(exc)[:180]}",\n            )\n\n        failure = (\n            "⚠️ This setup screen could not update safely. Reopen `/dank setup` "\n            "to continue. I did not open a second competing setup panel."\n        )\n        try:\n            if interaction.response.is_done():\n                await interaction.followup.send(failure, ephemeral=True)\n            else:\n                await interaction.response.send_message(failure, ephemeral=True)\n            _setup_interaction_log("panel_fork_blocked", interaction)\n            return\n        except Exception as exc:\n            _setup_interaction_log(\n                "panel_fork_notice_failed",\n                interaction,\n                error=f"{type(exc).__name__}:{str(exc)[:180]}",\n            )\n            raise RuntimeError("setup interaction could not update the clicked message") from (primary_error or exc)\n\n    # Slash-command/non-component callers do not have a clicked message, so a\n    # normal private response/follow-up remains the correct recovery route.\n    try:\n        if interaction.response.is_done():\n            await interaction.followup.send(\n                embed=embed,\n                view=view,\n                ephemeral=True,\n                allowed_mentions=discord.AllowedMentions.none(),\n            )\n            route = "followup.send"\n        else:\n            await interaction.response.send_message(\n                embed=embed,\n                view=view,\n                ephemeral=True,\n                allowed_mentions=discord.AllowedMentions.none(),\n            )\n            route = "response.send_message"\n        _setup_interaction_log("non_component_recovery_ok", interaction, route=route)\n    except Exception as exc:\n        _setup_interaction_log(\n            "non_component_recovery_failed",\n            interaction,\n            error=f"{type(exc).__name__}:{str(exc)[:180]}",\n        )\n        raise RuntimeError("setup interaction response failed") from (primary_error or exc)\n\n\nasync def _send_ephemeral(\n    interaction: discord.Interaction,\n    *,\n    embed: discord.Embed,\n    view: Optional[discord.ui.View] = None,\n) -> None:\n    try:\n        if interaction.response.is_done():\n            await interaction.followup.send(\n                embed=embed,\n                view=view,\n                ephemeral=True,\n                allowed_mentions=discord.AllowedMentions.none(),\n            )\n            route = "followup.send"\n        else:\n            await interaction.response.send_message(\n                embed=embed,\n                view=view,\n                ephemeral=True,\n                allowed_mentions=discord.AllowedMentions.none(),\n            )\n            route = "response.send_message"\n        _setup_interaction_log("private_send_ok", interaction, route=route)\n    except Exception as exc:\n        _setup_interaction_log(\n            "private_send_failed",\n            interaction,\n            error=f"{type(exc).__name__}:{str(exc)[:180]}",\n        )\n        raise\n''',
)

