# Permanent runtime-integrity regression.
(ROOT / "tests/test_setup_runtime_integrity_200.py").write_text(
    '''from __future__ import annotations\n\nimport asyncio\nfrom types import SimpleNamespace\nfrom typing import Any\n\nimport discord\n\nfrom stoney_verify.commands_ext import public_setup_compact as runtime\nfrom stoney_verify.commands_ext import public_setup_recommend as recommend\nfrom stoney_verify.commands_ext import public_setup_solid as solid\nfrom stoney_verify.setup_ui import public_setup_compact as compact\nfrom stoney_verify.setup_ui import public_setup_guided_test as guided\n\n\ndef _children(view: discord.ui.View) -> list[str]:\n    return [str(getattr(item, "custom_id", "")) for item in view.children if getattr(item, "custom_id", None)]\n\n\ndef test_final_runtime_reasserts_guided_owner_after_compact_drift() -> None:\n    recommend.SetupReviewView = compact.CompactReviewView\n    recommend.ProductSetupHomeView = compact.CompactSetupHomeView\n    recommend.LaunchTestView = compact.CompactTestView\n    recommend._open_test_launch = compact._open_tests\n\n    runtime.apply_public_setup_runtime()\n\n    assert recommend.SetupReviewView is guided.GuidedReviewView\n    assert recommend.ProductSetupHomeView is guided.GuidedSetupHomeView\n    assert recommend.LaunchTestView is guided.GuidedTestView\n    assert recommend._open_test_launch is guided.open_guided_tests\n\n    async def scenario() -> None:\n        view = recommend.SetupReviewView(ready=True)\n        items = {str(getattr(item, "custom_id", "")): item for item in view.children}\n        assert items["dank_setup_review:next"].label == "Start Guided Test"\n\n    asyncio.run(scenario())\n\n\ndef test_guided_test_session_survives_message_replacement() -> None:\n    compact._TEST_SESSIONS.clear()\n    state = {\n        "tickets": True,\n        "verification": False,\n        "basic_verify": False,\n        "voice_verify": False,\n        "id_verify": False,\n        "spam_guard": False,\n        "logs": True,\n        "completed": False,\n    }\n    first = SimpleNamespace(\n        guild=SimpleNamespace(id=10),\n        user=SimpleNamespace(id=20),\n        message=SimpleNamespace(id=30),\n    )\n    replacement = SimpleNamespace(\n        guild=SimpleNamespace(id=10),\n        user=SimpleNamespace(id=20),\n        message=SimpleNamespace(id=999),\n    )\n    saved = compact._save_test_session(first, state, {"tickets"})\n    assert saved == frozenset({"tickets"})\n    assert compact._load_test_session(replacement, state) == frozenset({"tickets"})\n\n\ndef test_edit_recovery_targets_clicked_message_instead_of_forking_panel() -> None:\n    events: list[str] = []\n\n    class Response:\n        def is_done(self) -> bool:\n            return True\n\n    class Message:\n        id = 333\n\n        async def edit(self, **kwargs: Any) -> None:\n            assert isinstance(kwargs.get("embed"), discord.Embed)\n            events.append("message-edit")\n\n    class Followup:\n        async def send(self, *args: Any, **kwargs: Any) -> None:\n            events.append("followup")\n\n    async def broken_original(**kwargs: Any) -> None:\n        _ = kwargs\n        raise RuntimeError("simulated original-response mismatch")\n\n    interaction = SimpleNamespace(\n        id=123,\n        data={"custom_id": "dank_setup_review:next"},\n        response=Response(),\n        message=Message(),\n        followup=Followup(),\n        edit_original_response=broken_original,\n        guild=SimpleNamespace(id=1),\n        user=SimpleNamespace(id=2),\n    )\n\n    asyncio.run(\n        solid._edit_or_followup(\n            interaction,\n            embed=discord.Embed(title="Recovered"),\n            view=None,\n        )\n    )\n    assert events == ["message-edit"]\n\n\ndef test_active_setup_views_have_unique_component_ids() -> None:\n    async def scenario() -> None:\n        state = {\n            "tickets": True,\n            "verification": False,\n            "basic_verify": False,\n            "voice_verify": False,\n            "id_verify": False,\n            "spam_guard": False,\n            "logs": True,\n            "completed": False,\n        }\n        views = [\n            guided.GuidedSetupHomeView(ready=True, started=True, completed=False),\n            compact.CompactManagerView(),\n            compact.CompactAdvancedView(),\n            guided.GuidedReviewView(ready=True),\n            guided.GuidedTestView(state, confirmed=frozenset()),\n            guided.GuidedFeatureTestView(state, frozenset(), "tickets"),\n        ]\n        for view in views:\n            ids = _children(view)\n            assert len(ids) == len(set(ids)), (type(view).__name__, ids)\n\n    asyncio.run(scenario())\n''',
    encoding="utf-8",
)

# Permanent source/runtime audit so this exact ownership drift cannot quietly
# return after a future setup refactor.
(ROOT / "tools/audit_setup_runtime_integrity.py").write_text(
    '''from __future__ import annotations\n\nfrom pathlib import Path\n\nROOT = Path(__file__).resolve().parents[1]\n\n\ndef source(path: str) -> str:\n    return (ROOT / path).read_text(encoding="utf-8")\n\n\ndef main() -> None:\n    gate = source("stoney_verify/commands_ext/public_setup_gate.py")\n    wrapper = source("stoney_verify/commands_ext/public_setup_compact.py")\n    guided = source("stoney_verify/setup_ui/public_setup_guided_test.py")\n    compact = source("stoney_verify/setup_ui/public_setup_compact.py")\n    solid = source("stoney_verify/commands_ext/public_setup_solid.py")\n    handler = source("stoney_verify/interaction_handlers.py")\n\n    assert "apply_public_setup_runtime" in gate\n    assert "from .public_setup_compact import apply_compact_setup_patch" not in gate\n    assert "_assert_runtime_ownership" in wrapper\n    assert "compact -> guided -> contracts" in wrapper\n    assert "if _PATCHED:\\n        return" not in guided\n    assert "Start Guided Test" in compact\n    assert "tuple[int, int, int]" not in compact\n    assert "panel_fork_blocked" in solid\n    assert "direct_message_recovery_ok" in solid\n    assert "except Exception:\\n        pass\\n\\n\\nasync def _edit_or_followup" not in solid\n    assert "dank_setup" not in handler, "generic interaction router must not steal setup view callbacks"\n\n    # The retired service-mode button that used to spawn a second setup message\n    # must remain unreferenced outside its compatibility module.\n    refs = []\n    for path in ROOT.rglob("*.py"):\n        if path.name == "setup_service_modes.py":\n            continue\n        text = path.read_text(encoding="utf-8", errors="ignore")\n        if "OpenServiceModeButton" in text:\n            refs.append(str(path.relative_to(ROOT)))\n    assert not refs, refs\n\n    from stoney_verify.commands_ext import public_setup_compact as runtime\n    from stoney_verify.commands_ext import public_setup_recommend as recommend\n    from stoney_verify.setup_ui import public_setup_guided_test as guided_runtime\n\n    runtime.apply_public_setup_runtime()\n    assert recommend.SetupReviewView is guided_runtime.GuidedReviewView\n    assert recommend.ProductSetupHomeView is guided_runtime.GuidedSetupHomeView\n    assert recommend.LaunchTestView is guided_runtime.GuidedTestView\n    assert recommend._open_test_launch is guided_runtime.open_guided_tests\n\n    print("DS-SETUP-039 runtime integrity audit passed")\n\n\nif __name__ == "__main__":\n    main()\n''',
    encoding="utf-8",
)

(ROOT / "ACTIVE_TASK.md").write_text(
    '''# ACTIVE TASK\n\n## DS-SETUP-039 — `/dank setup` runtime integrity and stale-path cleanup\n\n**Status:** IMPLEMENTING / VALIDATION PENDING\n**Branch:** `fix/setup-runtime-integrity-200`\n**Base:** `1fa23d361a65feaa8af51ca88dab6fb1a0257857` (`main`, squash merge of PR #199)\n**Started:** 2026-09-11\n\n## Production failure\n\nAfter `/dank setup` became public, live mobile testing showed component presses visibly acknowledge but sometimes fail to update the current setup screen; later navigation can reveal the action/state elsewhere. The live Configuration Check also showed the older **Test Features** view instead of the intended **Start Guided Test** final presentation.\n\n## Confirmed root causes / integrity risks\n\n1. The late `public_setup_gate` re-applied compact setup after the guided layer, while the guided installer was one-shot (`_PATCHED`) and could not reclaim ownership. This allowed a mixed old/new callback graph.\n2. `public_setup_solid._edit_or_followup` silently swallowed edit failures and spawned a new ephemeral setup view as fallback. Two active setup messages can then coexist and make navigation/state appear on the wrong screen.\n3. Guided-test session state was keyed by `(guild, user, message_id)`, so any message replacement/fallback split one logical setup session into separate state buckets.\n4. The generic interaction router does not own setup custom IDs; this is a setup presentation/response-routing problem, not the ticket/verify router stealing the click.\n5. Retired service-mode compatibility UI still exists for helper compatibility, but its old second-message button is not referenced by the active public setup path.\n\n## Repair\n\n- one deterministic final setup runtime installer: compact -> guided -> navigation/health contracts;\n- guided bindings are re-entrant and reassertable after any late compact install;\n- final runtime ownership assertions fail startup/tests if setup drifts again;\n- setup edits log their exact custom ID/message/route;\n- component edit recovery targets the clicked message directly;\n- a failed component edit can no longer silently create a second active setup panel;\n- guided test progress is scoped to guild + owner, not one ephemeral message ID;\n- permanent runtime/source audit and regressions cover final ownership, unique active component IDs, session continuity, and no generic-router interception.\n\n## Required validation\n\n- focused setup tests + new DS-SETUP-039 regressions;\n- permanent setup-runtime audit;\n- compile and diff check;\n- full repository exact-head CI;\n- review/base/scope check before squash merge;\n- post-merge main CI + exact Discloud deployment;\n- live acceptance through every `/dank setup` home/review/guided-test/feature-area/back/close transition with setup_runtime telemetry showing in-place edits only.\n''',
    encoding="utf-8",
)

